{"begin":"BEGIN_FSV-S04_repair_MAIN","stage":"repair","output":{"status":"READY","rego":"package external_pilot

import rego.v1

default allow := false

allow if {
    input.subject.role == "authenticated_api_caller"
    input.action == "POST /api/resource/Lead"
    input.resource.system == "ERPNext"
    input.resource.version == "16.0.0"
    regex.match("^[^@]+@[^@]+\\.[^@]+$", input.request.body.email_id)
}","reason":"Prior policy allowed all authenticated callers without validating request body fields. Developer tests reveal that email_id must be a valid email (Lead doctype field has options='Email'). Positive test expects allow for a properly formatted email; negative test expects deny for an invalid email. Added regex.match on /request/body/email_id to enforce email format, preserving default-deny and all existing role/action/resource checks."},"end":"END_FSV-S04_repair_MAIN"}
